TLM.f("Sancti/12-02",{"officium":"S. Bibianæ Virginis et Martyris","rule":["vide C6a;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6a","from":{"Introitus":"Commune/C6a","Lectio":"Commune/C6a","Graduale":"Commune/C6a","GradualeP":"Commune/C6a","Tractus":"Commune/C6a","Evangelium":"Commune/C6a","Offertorium":"Commune/C6a","Communio":"Commune/C6a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:95-96"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, ómnium largítor bonórum, qui in fámula tua Bibiána cum virginitátis flore martýrii palmam conjunxísti: mentes nostras ejus intercessióne tibi caritáte conjúnge; ut, amótis perículis, prǽmia consequámur ætérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:13-17"},{"k":"text","la":"Dómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum.","mark":"V"},{"k":"ref","la":"Sap 4:1"},{"k":"text","la":"O quam pulchra et casta generátio cum claritáte! Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti"},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"},{"k":"rubric","la":"Tempore paschali omittitur graduale."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beátæ Bibiánæ Vírginis et Mártyris tuæ dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:121; 118:122; 118:128"},{"k":"text","la":"Feci judícium et justítiam, Dómine, non calumniéntur mihi supérbi: ad ómnia mandáta tua dirigébar, omnem viam iniquitátis ódio hábui. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Divíni múneris largitáte satiáti, quǽsumus, Dómine, Deus noster: ut, intercedénte beáta Bibiánæ Vírgine et Mártyre tua, in ejus semper participatióne vivámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9f9c6ab7f4db3841":{"t":"Ps 118, 95-96, Ps 118, 1\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena. (Ps 118, 1) Blago neokaljanima na životnom putu, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena.","kn":"(Ps. 118, 95, 96). Na mene vrebaju grješnici, da me upropaste, a ja razmišljam Tvoj zako-n. Gospodine! Vidjeh, da ima svršetak sve, ma kako bilo veliko, samo je zakon Tvoj neizmjeran i bez kraja-. (Aleluja. Aleluja). (Ps. 118, 1). Blago onima, koji su čista života, koji žive po zakonu Gospodnjem! Slava Ocu. Na mene.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"167feed1aa6326f2":{"t":"<i>Pomolimo se</i>.\nBože, djelitelju svih dobara, koji si u svojoj službenici Bibijani sjedinio s cvijetom djevičanstva mučeničku palmu, sjedini po njezinu zagovoru naše duše sa sobom u ljubavi, da ođstranivši pogibelji postignemo vječnu nagradu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Bože, darovatelju svih dobara, koji si u službenici svojoj Bibijani sjedinio cvijet djevičanstva s paomom mučeništva, sjedini njezinim zagovorom naše duše s Tobom, da uklonivši se pogiblima dostignemo vječne nagrade, po G. n.","knRef":"Kniewald 1942, str. 448–449 (snimka 225) (OCR)"},"68b7d4adafa31fe1":{"t":"Sir 51, 13-17\nČitanje knjige Mudrosti. Bože Gospodaru moj, uzdigao si me s mojeg prebivališta na zemlji, a ja sam molila da me mine smrt koja me zarobila. Zazvala sam Gospodina, Oca moga Gospodara, da me u vrijeme oholica ne ostavi bez pomoći na dan mojih muka. Hvalit ću te bez prestanka i slavit ću te priznavanjem, jer si uslišao moju molitvu. Izbavio si me od propasti i spasio u vrijeme nepravde. Zato ću te slaviti i hvaliti, Gospodine Bože naš.","kn":"Čitanje Knjige mudrosti (Crkv. 51, 13-17); Gospodine Bože -moj, uzdigao si moje prebivalište sa zemlje, a ja sam molila, da me mine smrt, koja se bacila na me. Zazvala sam Gospođina, Oca mojeg« Gospodina, da me ne ostavi u dan mojih muka i bez pomoći u vrijeme o-holica. Hvallt ću te neprestano i slavit ću te s priznavanjem, jer je uslišana moja molitva, izbavio si me od propasti i spasio u vrijeme nepravde. Zato ću te slaviti i hvaliti, Gospodine, Bože naš.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"b1d85c38b24adb78":{"t":"Ps 45, 6 i 5\nSnaga joj je promatranje lica Božjega. Bog je u njoj i neće se pokolebati. Nabujala rijeka veseli grad Božji. Svevišnji je posvetio prebivalište svoje.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je razborita djevica, jedna od onih mudrih. <i>Aleluja</i>.","kn":"(Ps. 45, 6). Štitit će je Gospodiri pred licem svojim; u gredu svome prebiva Bog, ne će se uzdrmati (Ps. 45, 5). Bujica rijećnih valova razveseljuje Božji grad, u home je Višnji izabrao sebi stan. Aleluja, Aleluja. Evo razborite djevice, jedne od mudrih, Aleluja.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"599856a3c73c1a30":{"t":"Mt 13, 44-52\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi koje, kad čovjek nađe, sakrije, te veseo ode i proda sve što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac koji traži prave bisere. I kad nađe jedan dragocjeni biser, ode i proda sve što ima i kupi ga. Nadalje kraljevstvo je nebesko kao mreža koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude a izbace zle. Tako će biti na svršetku svijeta. Izići će anđeli i odijeliti će opake od pravednih i bacit će ih u ognjenu peć. Ondje će biti plač i škripanje zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik koji je poučen u tajnama kraljevstva nebeskoga kao domaćin koji od svoga blaga iznosi novo i staro.","kn":"t Slijedi sv. evanđelje po Matejn (13, 44-52). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi, koje, kad čovjek nađe, sakrije, te veseo ode i proda sve, što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac, koji traži pravo biserje. I kad nađe jedan dragocjeni biser, ode i proda sve, što ima i kupi ga. Nadalje kraljevstvo^ je nebesko kao mreža, koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude, a izbace zle. Tako će biti na svršetku svijeta: Izići će anđeli i odijelit će opake od pravednih i bacit će ih u ognjenu peć; ondje će biti plač i škripa zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik,, koji je poučen u tajnaman kraljevstva nebeskoga, kao domaćin, koji od svoga blaga iznosi novo i staro.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"f13ce0f2fb02da20":{"t":"Ps 44, 3\nRazlita je milina na tvojim usnama, zbog toga te Bog blagoslovi u vijeke, i u vijeke vjekova.","kn":"(Ps. 44, 3). Razlita je milost na usnama tvojim, toga radi blagoslovi te Bog u vijeke, i u vijeke vijeka.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"4bb5ea25a19b334c":{"t":"Dobrostivo primi, Gospodine, žrtvene darove koje ti posvećujemo po zaslugama blažene Bibijane djevice tvoje i mučenice, i daj da nam budu na neprestanu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blažene I., djevice i mučenice 1 podaj, da nam ishode Tvoju neprestanu pomoć. Po G. n.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"85c6faa6661f99fa":{"t":"Ps 118, 121 i 122 i 128\nČinim što je dobro i pravo, Gospodine. Ne daj da me ozloglase oholi. Držim se tvojih zapovijedi, a mrzim svaki nevaljali put.","kn":"(Ps. 118, 121, 128). Ja činim, što je pravo pred Tobom, Gospodine, ne daj, da me upropaste oholi; znam, pravedna je svaka Tvoja odredba., ja mrzim put nepravde.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"5c16f11e7881e5bb":{"t":"<i>Pomolimo se</i>.\nNasićeni obilnim Božjim darovima, molimo, Gospodine Bože naš, da po zagovoru blažene Bibijane tvoje djevice i mučenice, uvijek živimo sudjelujući u njima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni obiljem nebeskoga dara molimo Te, Gospodine, Bože naš, da zagovorom blažene I., djevice i mučenice, uvijek živimo kao dionici ovih svetih tajna. Po G. n.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"}}});
